const monthMap: Record<string, number> = {
  Januari: 0, Februari: 1, Maret: 2, April: 3, Mei: 4, Juni: 5,
  Juli: 6, Agustus: 7, September: 8, Oktober: 9, November: 10, Desember: 11,
}

/**
 * Parse an Indonesian "d MMMM yyyy" date string into a Date.
 * Exported because the native `new Date(string)` parser only recognizes some
 * Indonesian month names (e.g. fails on "Agustus", "Desember") depending on
 * the runtime ICU data — this map-based parser is deterministic everywhere.
 */
export function parseDate(dateStr: string): Date {
  const [day, month, year] = dateStr.split(' ')
  return new Date(Number(year), monthMap[month] ?? 0, Number(day))
}

function sortPostsByDateDesc(p: BlogPost[]): BlogPost[] {
  return [...p].sort((a, b) => parseDate(b.date).getTime() - parseDate(a.date).getTime())
}

export function getAllPosts(): BlogPost[] {
  return sortPostsByDateDesc(posts)
}

export function getPostBySlug(slug: string): BlogPost | undefined {
  return posts.find((post) =>
    Object.values(post.translations).some((t) => t.slug === slug),
  )
}

/**
 * Determine a blog post's canonical language from its slug.
 * Every slug is unique to one locale's translation, so the slug itself
 * is the source of truth for the article's language.
 */
export function getPostLangFromSlug(slug: string): Lang | undefined {
  const post = getPostBySlug(slug)
  if (!post) return undefined
  for (const locale of ['id', 'en'] as const) {
    if (post.translations[locale]?.slug === slug) return locale
  }
  return undefined
}

/**
 * Get the slug for a specific locale of a post.
 * Returns undefined if the post has no translation for that locale.
 */
export function getPostSlugForLocale(post: BlogPost, locale: Lang): string | undefined {
  return post.translations[locale]?.slug
}

export function getFeaturedPosts(count: number = 3): BlogPost[] {
  return sortPostsByDateDesc(posts).slice(0, count)
}

/**
 * Unique blog categories for a locale, sorted alphabetically.
 * Derived dynamically from the posts data so new categories appear
 * automatically (used by the nav "Blog" submenu and filters).
 */
export function getBlogCategories(lang: Lang = 'en'): string[] {
  const cats = new Set<string>()
  for (const post of posts) {
    const t = post.translations[lang]
    if (t && t.category) cats.add(t.category)
  }
  return Array.from(cats).sort()
}

export function generatePostSchema(post: BlogPost, lang: Lang, slug?: string) {
  const t = post.translations[lang]!
  const canonicalSlug = slug ?? t.slug
  const isoDate = parseDate(post.date).toISOString()
  return {
    '@context': 'https://schema.org',
    '@type': 'BlogPosting',
    headline: t.title,
    description: t.excerpt,
    image: `https://farisium.com${post.image}`,
    datePublished: isoDate,
    dateModified: isoDate,
    author: {
      '@type': 'Person',
      name: 'M. Faris Deni K.',
      url: getCanonicalUrl(lang, '/'),
      image: 'https://farisium.com/faris.webp',
    },
    publisher: {
      '@type': 'Organization',
      name: 'Farisium',
      logo: {
        '@type': 'ImageObject',
        url: 'https://farisium.com/farisium-logo.png',
      },
    },
    mainEntityOfPage: {
      '@type': 'WebPage',
      '@id': getCanonicalUrl(lang, `/blog/${canonicalSlug}`),
    },
    inLanguage: lang,
    wordCount: t.content.reduce((acc, s) => {
      if (s.type === 'paragraph') {
        return acc + (s.text ?? '').split(/\s+/).filter(Boolean).length
      }
      if (s.type === 'list') {
        const words = (s.items ?? []).reduce(
          (sum, item) => sum + item.split(/\s+/).filter(Boolean).length,
          0,
        )
        return acc + words
      }
      return acc
    }, 0),
  }
}

export function generateFAQSchema(
  faqs: { question: string; answer: string }[],
) {
  return {
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: faqs.map((faq) => ({
      '@type': 'Question',
      name: faq.question,
      acceptedAnswer: {
        '@type': 'Answer',
        text: faq.answer,
      },
    })),
  }
}

export function extractHeadings(
  content: BlogSection[],
): { id: string; text: string; level: number }[] {
  return content
    .filter((s): s is BlogSection & { text: string } => s.type === 'heading' && !!s.text)
    .map((s) => ({
      id: s.text.toLowerCase().replace(/\s+/g, '-').replace(/[^\w-]/g, ''),
      text: s.text,
      level: s.level ?? 2,
    }))
}

export function getRelatedPosts(
  currentSlug: string,
  category: string,
  lang: Lang,
  limit: number = 3,
): BlogPost[] {
  return posts
    .filter((post) => {
      const t = post.translations[lang]
      if (!t) return false
      const slugMatch = Object.values(post.translations).some((tt) => tt?.slug === currentSlug)
      return !slugMatch && t.category === category
    })
    .slice(0, limit)
}

export function generateBreadcrumbSchema(
  items: { name: string; item: string }[],
) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      name: item.name,
      item: item.item,
    })),
  }
}

export function generateCollectionPageSchema(posts: BlogPost[], lang: Lang) {
  return {
    '@context': 'https://schema.org',
    '@type': 'CollectionPage',
    name: lang === 'id' ? 'Blog Farisium' : 'Farisium Blog',
    description:
      lang === 'id'
        ? 'Artikel, tutorial, dan berita terbaru dari ekosistem Farisium.'
        : 'Articles, tutorials, and latest news from the Farisium ecosystem.',
    url: getCanonicalUrl(lang, '/blog'),
    mainEntity: {
      '@type': 'ItemList',
      itemListElement: posts.reduce((acc, post, i) => {
        const t = post.translations[lang]
        if (!t) return acc
        acc.push({
          '@type': 'ListItem',
          position: acc.length + 1,
          url: getCanonicalUrl(lang, `/blog/${t.slug}`),
        })
        return acc
      }, [] as Array<{ '@type': string; position: number; url: string }>),
    },
  }
}

export function extractFAQs(
  content: BlogSection[],
): { question: string; answer: string }[] {
  const faqs: { question: string; answer: string }[] = []
  for (let i = 0; i < content.length; i++) {
    const section = content[i]
    if (section.type !== 'heading' || section.level !== 3) continue
    const text = (section.text ?? '').toLowerCase()
    const isQuestion =
      text.startsWith('apakah') ||
      text.startsWith('apa') ||
      text.startsWith('bagaimana') ||
      text.startsWith('berapa') ||
      text.startsWith('is ') ||
      text.startsWith('what ') ||
      text.startsWith('how ') ||
      text.startsWith('can ') ||
      text.startsWith('does ') ||
      text.startsWith('are ') ||
      text.startsWith('which ') ||
      text.startsWith('will ') ||
      text.startsWith('who ') ||
      text.includes('perbedaan') ||
      text.includes('difference')
    if (!isQuestion) continue
    const question = section.text ?? ''
    const answerSection = content[i + 1]
    if (
      answerSection &&
      answerSection.type === 'paragraph' &&
      answerSection.text
    ) {
      faqs.push({ question, answer: answerSection.text })
    }
  }
  return faqs
}
